<?php
if(!defined('ABSPATH')){exit;}
final class AICS_External_Link_Validation_Service{
	private array $cache=array();
	public function validate(string $url,bool $verify=true){$url=esc_url_raw(trim($url),array('http','https'));if(''===$url||!wp_http_validate_url($url)||isset($this->cache[$url])){return $this->cache[$url]??new WP_Error('external_link_candidate_invalid');}$parts=wp_parse_url($url);$host=strtolower((string)($parts['host']??''));if(''===$host||isset($parts['user'])||isset($parts['pass'])||$this->blocked_host($host)||$this->blocked_path($url)){return $this->cache[$url]=new WP_Error('external_link_candidate_invalid');}if(!$verify){return $this->cache[$url]=array('url'=>$url,'status_code'=>0,'verified'=>false,'host'=>$host);}$response=wp_safe_remote_head($url,array('timeout'=>5,'redirection'=>0,'sslverify'=>true,'user-agent'=>'AI Content Studio URL Verifier'));if(is_wp_error($response)){return $this->cache[$url]=new WP_Error('external_link_verification_failed');}$code=wp_remote_retrieve_response_code($response);if($code>=300&&$code<400){$location=wp_remote_retrieve_header($response,'location');if(!is_string($location)||''===$location){return $this->cache[$url]=new WP_Error('external_link_verification_failed');}$final=$this->validate($location,false);if(is_wp_error($final)){return $this->cache[$url]=$final;}$response=wp_safe_remote_head($final['url'],array('timeout'=>5,'redirection'=>0,'sslverify'=>true,'user-agent'=>'AI Content Studio URL Verifier'));if(is_wp_error($response)){return $this->cache[$url]=new WP_Error('external_link_verification_failed');}$code=wp_remote_retrieve_response_code($response);$url=$final['url'];$host=$final['host'];}if($code<200||$code>=300){return $this->cache[$url]=new WP_Error('external_link_verification_failed');}return $this->cache[$url]=array('url'=>$url,'status_code'=>$code,'verified'=>true,'host'=>$host,'verified_at'=>current_time('mysql',true));}
	private function blocked_host(string $host):bool{if(in_array($host,array('localhost','localhost.localdomain'),true)||str_ends_with($host,'.local')||str_ends_with($host,'.internal')){return true;}$ips=array();if(filter_var($host,FILTER_VALIDATE_IP)){$ips[]=$host;}else{$resolved=gethostbynamel($host);if(is_array($resolved)){$ips=$resolved;}}if(!$ips){return true;}foreach($ips as $ip){if(false===filter_var($ip,FILTER_VALIDATE_IP,FILTER_FLAG_NO_PRIV_RANGE|FILTER_FLAG_NO_RES_RANGE)){return true;}}return false;}private function blocked_path(string $url):bool{$admin=wp_parse_url(admin_url(),PHP_URL_PATH);$login=wp_parse_url(wp_login_url(),PHP_URL_PATH);$path=(string)wp_parse_url($url,PHP_URL_PATH);return ($admin&&str_starts_with($path,$admin))||($login&&str_starts_with($path,$login));}
}
